import {messages,parseAI,outputSchema} from './prompts.js';
export async function discoverProviders(){let cloud=[];try{const r=await fetch('./api/config',{signal:AbortSignal.timeout(4000)});if(r.ok)cloud=(await r.json()).providers||[];}catch{}let browser='unavailable';try{if(globalThis.LanguageModel?.availability)browser=await LanguageModel.availability();}catch{}return {cloud,browser};}
export async function runAI(stage,data,settings,signal){if(settings.provider==='browser'){if(!globalThis.LanguageModel)throw Error('This browser does not expose a built-in language model. Choose another AI connection.');const availability=await LanguageModel.availability();if(availability==='unavailable')throw Error('Browser AI is unavailable on this device. Choose another connection.');let session;try{session=preparedBrowserSession;preparedBrowserSession=null;if(!session){if(availability!=='available')throw Error('Open Connect AI and prepare the browser model first.');session=await LanguageModel.create({signal});}const msg=messages(stage,data);const text=await session.prompt(msg.map(m=>m.content).join('\n\n'),{signal});return {result:parseAI(text,stage),provider:'browser',model:'Browser-provided LanguageModel',at:new Date().toISOString()};}finally{session?.destroy();}}
if(settings.provider==='ollama'){const base=new URL(settings.ollamaURL||'http://localhost:11434');if(!['localhost','127.0.0.1','[::1]'].includes(base.hostname)||base.protocol!=='http:'||base.username||base.password||base.search||base.hash||base.pathname!=='/')throw Error('Use a local Ollama address such as http://localhost:11434.');if(!settings.ollamaModel?.trim())throw Error('Enter the name of a model installed in Ollama.');let response;try{response=await fetch(base.origin+'/api/chat',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({model:settings.ollamaModel,messages:messages(stage,data).map((m,i)=>stage==='plan'&&i===1?{...m,content:m.content+'\nFor this request, return sections as an object keyed by the exact section titles, with plain-text string values, as required by the output schema.'}:m),stream:false,format:outputSchema(stage),think:false,options:{num_ctx:16384,num_predict:stage==='plan'?10000:2500}}),signal});}catch(error){if(signal?.aborted)throw error;throw Error('Cannot reach Ollama. Start Ollama, allow this site origin in OLLAMA_ORIGINS, and allow local-network access if your browser asks.');}if(!response.ok)throw Error(`Ollama returned HTTP ${response.status}. Check that the model is installed.`);const body=await response.json();return {result:parseAI(body.message?.content,stage),provider:'ollama',model:settings.ollamaModel,at:new Date().toISOString()};}
if(settings.provider==='custom'){const base=new URL(settings.baseURL);if(base.protocol!=='https:'||base.username||base.password||base.search||base.hash)throw Error('Use an HTTPS API base URL without credentials or query parameters.');let response;try{response=await fetch(base.href.replace(/\/$/,'')+'/chat/completions',{method:'POST',headers:{'Content-Type':'application/json',...(settings.apiKey?{Authorization:'Bearer '+settings.apiKey}:{})},body:JSON.stringify({model:settings.model,messages:messages(stage,data),stream:false}),signal,redirect:'error'});}catch{throw Error('The custom endpoint could not be reached. It must allow this browser origin through CORS.');}if(!response.ok)throw Error('Custom provider returned HTTP '+response.status);const result=await response.json();return {result:parseAI(result.choices?.[0]?.message?.content,stage),provider:'custom',model:settings.model,at:new Date().toISOString()};}if(settings.provider==='guided')throw Error('Connect an AI assistant first. Guided tools remain available without AI.');const response=await fetch('./api/ai',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({provider:settings.provider==='ollama-bridge'?'local-server':settings.provider,stage,data,...(settings.provider==='ollama-bridge'?{credentials:{model:settings.ollamaModel}}:settings.apiKey?{credentials:{apiKey:settings.apiKey,model:settings.model}}:{})}),signal});let body;try{body=await response.json();}catch{throw Error('The AI gateway is unavailable. Use browser AI, Ollama, or guided mode.');}if(!response.ok)throw Error(body.error||'AI request failed');return body;}

let preparedBrowserSession=null;
export async function prepareBrowserAI(onProgress=()=>{}){
 if(!globalThis.LanguageModel?.create)throw Error('This browser does not expose the built-in LanguageModel API.');
 preparedBrowserSession?.destroy();preparedBrowserSession=null;
 preparedBrowserSession=await LanguageModel.create({monitor(m){m.addEventListener('downloadprogress',event=>onProgress(Math.round(event.loaded*100)));}});
 return 'available';
}
export async function detectOllama(address='http://localhost:11434',fetcher=fetch){
 const base=new URL(address);if(base.protocol!=='http:'||!['localhost','127.0.0.1','[::1]'].includes(base.hostname)||base.username||base.password||base.pathname!=='/'||base.search||base.hash)throw Error('Use a loopback Ollama address.');
 try{const bridge=await fetcher('./api/ollama/models',{signal:AbortSignal.timeout(6000)});if(bridge.ok){const data=await bridge.json();return {models:data.models||[],transport:'local-server'};}}catch{}
 try{const response=await fetcher(base.origin+'/api/tags',{signal:AbortSignal.timeout(6000)});if(!response.ok)throw Error();const data=await response.json();return {models:(data.models||[]).filter(m=>typeof m.name==='string').map(m=>({name:m.name,size:m.size})),transport:'browser'};}catch{throw Error('Cannot detect Ollama. Start it, allow this site in OLLAMA_ORIGINS, and permit local-network access when prompted.');}
}
